import React, { useCallback, useState } from 'react';
import { graphql } from 'gatsby';
import Layout from '../components/layout';
import Seo from '../components/seo';
import PostItem from '../components/post-item';
import {
 SearchInputForm,
 SearchIcon,
 Tag,
 PostListWrapper,
 CenterPos,
 MainContainer,
 SideContainer,
 PostListContainer,
 Profile,
 Name,
 ProfileEmoji,
 MobileContainer,
 MobileEmoji,
 MobileName,
 MobileProfile,
 CategoryTitle,
 RightSideContainer,
 TagList,
 FlexWrapper,
 Description,
} from '../style/blogMainStyle';
import { StaticImage } from 'gatsby-plugin-image';

// const ALL_NAME = 'ALL';

const BlogIndex = ({ data, location }) => {
 const siteTitle = data.site.siteMetadata?.title || 'Title';
 const allPosts = data.allMarkdownRemark.nodes;
 const [posts, setPosts] = useState([...allPosts]);
 const [keyword, setKeyword] = useState('');

 const onChangeKeyword = useCallback((e) => {
  setKeyword(e.target.value);
 }, []);

 const searchProc = useCallback(
  (e) => {
   e.preventDefault();
   if (!keyword || !keyword.trim()) {
    setPosts([...allPosts]);
    return;
   }
   setPosts([
    ...allPosts.filter((post) => {
     if (post.frontmatter.title?.includes(keyword) || post.frontmatter.description?.includes(keyword)) {
      return true;
     }
    }),
   ]);
  },
  [keyword],
 );

 return (
  <Layout location={location} title={siteTitle}>
   <MainContainer>
    <div>
     <Profile>
      {/* <StaticImage
       src="../images/profile.png"
       alt="프로필 이미지"
       placeholder="blurred"
       layout="fixed"
       width={170}
       height={150}
       style={{ borderRadius: '10px' }}
      /> */}
      <div>
       <Name>
        heeyoung
        <div>Frontend Engineer</div>
       </Name>
       <Description>더 나은 사용자 경험을 위한 기술과 디자인을 탐구합니다</Description>
      </div>
     </Profile>
    </div>
    <PostListContainer>
     <FlexWrapper>
      <CategoryTitle>
       All
       <div>{posts.length} 개의 글</div>
      </CategoryTitle>
      <SearchInputForm onSubmit={searchProc}>
       <input type="text" value={keyword} onChange={onChangeKeyword} placeholder="Search..." />
       <SearchIcon>🔎</SearchIcon>
      </SearchInputForm>
     </FlexWrapper>
     <PostListWrapper style={{ listStyle: 'none' }}>
      {posts.length === 0 && <CenterPos>포스트가 존재하지 않습니다.</CenterPos>}
      {posts.map((post) => {
       const title = post.frontmatter.title || post.fields.slug;
       return <PostItem key={post.fields.slug} title={title} post={post} />;
      })}
     </PostListWrapper>
    </PostListContainer>
   </MainContainer>
  </Layout>
 );
};

export default BlogIndex;

/**
 * Head export to define metadata for the page
 *
 * See: https://www.gatsbyjs.com/docs/reference/built-in-components/gatsby-head/
 */
export const Head = () => <Seo title="klloo" />;

export const pageQuery = graphql`
 {
  site {
   siteMetadata {
    title
   }
  }
  allMarkdownRemark(sort: { frontmatter: { date: DESC } }) {
   nodes {
    excerpt(pruneLength: 200, truncate: true)
    fields {
     slug
    }
    frontmatter {
     date(formatString: "MMMM DD, YYYY")
     title
     description
     category
     icon
     tags
    }
   }
  }
 }
`;
